render: function () {
  var self = this;
  var filtered = this.filteredTodos();
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var countEl = document.querySelector('.todo-count');
  var clearBtn = document.querySelector('.clear-completed');
  var toggleAll = document.querySelector('.toggle-all');

  // Show/hide main and footer
  var hasTodos = this.todos.length > 0;
  main.style.display = hasTodos ? 'block' : 'none';
  footer.style.display = hasTodos ? 'block' : 'none';

  // Render list
  todoList.innerHTML = '';
  filtered.forEach(function (todo) {
    var li = document.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) { li.classList.add('completed'); }

    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + self.escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + self.escapeHtml(todo.title) + '">';

    var toggle = li.querySelector('.toggle');
    toggle.addEventListener('click', function () {
      self.todos = todoModel.toggleTodo(todo.id);
      self.render();
    });

    var destroyBtn = li.querySelector('.destroy');
    destroyBtn.addEventListener('click', function () {
      self.todos = todoModel.deleteTodo(todo.id);
      self.render();
    });

    var label = li.querySelector('label');
    label.addEventListener('dblclick', function () {
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.value = label.textContent.trim();
      editInput.focus();
      if (editInput.setSelectionRange) {
        editInput.setSelectionRange(editInput.value.length, editInput.value.length);
      }
    });

    var editInput = li.querySelector('.edit');
    editInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        self.commitEdit(li, todo.id, editInput);
      } else if (e.keyCode === ESCAPE_KEY) {
        li.classList.remove('editing');
        editInput.value = label.textContent.trim();
      }
    });
    editInput.addEventListener('blur', function () {
      if (!li.classList.contains('editing')) { return; }
      self.commitEdit(li, todo.id, editInput);
    });

    todoList.appendChild(li);
  });

  // Counter
  var activeCount = todoModel.getActiveCount();
  var itemWord = activeCount === 1 ? 'item' : 'items';
  countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

  // Clear completed visibility
  var completedCount = todoModel.getCompletedCount();
  clearBtn.style.display = completedCount > 0 ? 'block' : 'none';

  // Toggle all state
  toggleAll.checked = this.todos.length > 0 && activeCount === 0;
},

edits.newText:
render: function () {
  var self = this;
  var filtered = this.filteredTodos();
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var countEl = document.querySelector('.todo-count');
  var clearBtn = document.querySelector('.clear-completed');
  var toggleAll = document.querySelector('.toggle-all');

  // Show/hide main and footer
  var hasTodos = this.todos.length > 0;
  main.style.display = hasTodos ? 'block' : 'none';
  footer.style.display = hasTodos ? 'block' : 'none';

  // Build a lookup of visible todo IDs
  var visibleIds = {};
  filtered.forEach(function (t) { visibleIds[t.id] = true; });

  // Build a lookup of current DOM items by data-id
  var currentItems = {};
  var currentOrder = [];
  var liveLis = todoList.querySelectorAll('li');
  liveLis.forEach(function (li) {
    currentItems[li.dataset.id] = li;
    currentOrder.push(li.dataset.id);
  });

  // Remove items that should no longer be visible
  currentOrder.forEach(function (id) {
    if (!visibleIds[id]) {
      var li = currentItems[id];
      if (li && li.parentNode) { li.parentNode.removeChild(li); }
    }
  });

  // Render or update each item, keeping existing DOM nodes in place
  filtered.forEach(function (todo, idx) {
    var existingLi = currentItems[todo.id];
    if (existingLi) {
      // Update existing element in place — preserves DOM references
      if (todo.completed) {
        existingLi.classList.add('completed');
      } else {
        existingLi.classList.remove('completed');
      }
      var toggle = existingLi.querySelector('.toggle');
      if (toggle) { toggle.checked = todo.completed; }
      var label = existingLi.querySelector('label');
      if (label) { label.textContent = todo.title; }
      var edit = existingLi.querySelector('.edit');
      if (edit && edit !== document.activeElement) { edit.value = todo.title; }
      // Move to correct position if needed
      var expectedPrev = idx === 0 ? null : currentItems[filtered[idx - 1].id];
      var actualPrev = existingLi.previousElementSibling;
      if (expectedPrev !== actualPrev) {
        var refNode = expectedPrev ? expectedPrev.nextElementSibling : todoList.firstChild;
        if (refNode !== existingLi) {
          todoList.insertBefore(existingLi, refNode);
        }
      }
    } else {
      // Create new element
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) { li.classList.add('completed'); }

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + self.escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + self.escapeHtml(todo.title) + '">';

      (function (todoId, itemEl) {
        var toggle = itemEl.querySelector('.toggle');
        toggle.addEventListener('click', function () {
          self.todos = todoModel.toggleTodo(todoId);
          self.render();
        });

        var destroyBtn = itemEl.querySelector('.destroy');
        destroyBtn.addEventListener('click', function () {
          self.todos = todoModel.deleteTodo(todoId);
          self.render();
        });

        var label = itemEl.querySelector('label');
        label.addEventListener('dblclick', function () {
          itemEl.classList.add('editing');
          var editInput = itemEl.querySelector('.edit');
          editInput.value = label.textContent.trim();
          editInput.focus();
          if (editInput.setSelectionRange) {
            editInput.setSelectionRange(editInput.value.length, editInput.value.length);
          }
        });

        var editInput = itemEl.querySelector('.edit');
        editInput.addEventListener('keydown', function (e) {
          if (e.keyCode === ENTER_KEY) {
            self.commitEdit(itemEl, todoId, editInput);
          } else if (e.keyCode === ESCAPE_KEY) {
            itemEl.classList.remove('editing');
            editInput.value = label.textContent.trim();
          }
        });
        editInput.addEventListener('blur', function () {
          if (!itemEl.classList.contains('editing')) { return; }
          self.commitEdit(itemEl, todoId, editInput);
        });
      })(todo.id, li);

      // Insert at correct position
      var refNode = idx === 0 ? todoList.firstChild : (currentItems[filtered[idx - 1].id] ? currentItems[filtered[idx - 1].id].nextElementSibling : todoList.firstChild);
      todoList.insertBefore(li, refNode);
      currentItems[todo.id] = li;
    }
  });

  // Counter
  var activeCount = todoModel.getActiveCount();
  var itemWord = activeCount === 1 ? 'item' : 'items';
  countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

  // Clear completed visibility
  var completedCount = todoModel.getCompletedCount();
  clearBtn.style.display = completedCount > 0 ? 'block' : 'none';

  // Toggle all state
  toggleAll.checked = this.todos.length > 0 && activeCount === 0;
},

